const story=document.querySelector('.editorial-story');const storyReduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let chapter=-1,scheduled=false;
const chapters=[['LE CORPS.','L’ESPRIT.','Tout commence\npar un salut.','Le respect avant la technique. La confiance avant la performance. Une école de vie, dès 3 ans.'],['APPRENDRE.','SE RELEVER.','Tomber. Apprendre.\nRecommencer.','Du Baby Judo aux cours confirmés, chaque geste se construit avec patience. Chacun avance à son rythme.'],['PROGRESSER.','ENSEMBLE.','Une force\ncollective.','Trois dojos à Cayenne, une même famille. Les plus expérimentés transmettent aux plus jeunes.']];
function updateStory(){scheduled=false;const r=story.getBoundingClientRect();const progress=storyReduced?0:Math.max(0,Math.min(1,-r.top/Math.max(1,r.height-innerHeight)));story.style.setProperty('--story-progress',progress);window.dispatchEvent(new CustomEvent('judoka-scroll',{detail:{progress}}));const next=Math.min(2,Math.floor(progress*3));if(next!==chapter){chapter=next;const c=chapters[next];document.querySelector('#story-line-1').textContent=c[0];document.querySelector('#story-line-2').textContent=c[1];document.querySelector('#story-title').textContent=c[2];document.querySelector('#story-title').style.whiteSpace='pre-line';document.querySelector('#story-text').textContent=c[3];document.querySelector('#story-number').textContent='0'+(next+1);story.dataset.chapter=String(next);}}
addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateStory)}},{passive:true});addEventListener('resize',updateStory);updateStory();
